Select * FROM customer;

-- 1. What is the total revenue generated by male vs female customers.
SELECT gender,SUM(purchase_amount) revenue
FROM customer
GROUP BY gender;

-- 2. Which customers used a discount but still spent more than the average purchase amount.
SELECT customer_id,purchase_amount FROM customer WHERE discount_applied = 'Yes' AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer);


-- 3. Which are the top 5 products with the highest average review rating.
SELECT item_purchased, ROUND(AVG(review_rating),2) Average_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- 4. Compare the average purchase amount between standard and express shipping.
SELECT shipping_type, AVG(purchase_amount) Average_purchase_amount
FROM customer
WHERE shipping_type IN('Standard','Express')
GROUP BY shipping_type;


-- 5. Do subscribed customers spend more? Compare average spend and total revenue between subscribed and non-subscribed customers. 
SELECT subscription_status, COUNT(customer_id) total_customers, AVG(purchase_amount) avg_spend, SUM(purchase_amount) total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;


-- 6. Which 5 products has the highest percentage of purchases with discount applied?
SELECT item_purchased,
ROUND(SUM(CASE WHEN discount_applied = "Yes" THEN 1 ELSE 0 END)/COUNT(*)*100,2) discount_percent
FROM customer
GROUP BY item_purchased
ORDER BY discount_percent DESC
LIMIT 5;


-- 7. Segment customers into New, Returning and Loyal based on their total number of previous purchases and show the count of each segment
WITH customer_type AS(
SELECT customer_id, previous_purchases,
CASE 
	WHEN previous_purchases = 1 THEN 'New customer'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning customer'
	ELSE 'Loyal customer' 
    END AS customer_segment
FROM customer
)

SELECT customer_segment, COUNT(*) total_customers
FROM customer_type
GROUP BY customer_segment;


-- 8. What are the top 3 most purchased products within each category. 
WITH item_rn AS(
SELECT item_purchased,category, COUNT(customer_id) total_orders,
ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) item_rank
FROM customer
GROUP BY category,item_purchased
)

SELECT category, item_purchased, total_orders, item_rank
FROM item_rn
WHERE item_rank <= 3;


-- 9. Are customers who are repeat buyers (more than 5 previous purchases) are likely to subscribe?
SELECT subscription_status, COUNT(customer_id)
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;


-- 10. What is the revenue contribution of each age group
SELECT age_group, SUM(purchase_amount) revenue
FROM customer
GROUP BY age_group
ORDER BY revenue DESC;













